# Product-owned Windows consumer bootstrap. Generated by `sc-lint init --just`.
$InvocationArguments = @($args)
$Operation = if ($InvocationArguments.Count -gt 0) { $InvocationArguments[0] } else { $null }
$Rest = if ($InvocationArguments.Count -gt 1) { @($InvocationArguments | Select-Object -Skip 1) } else { @() }

function Stop-Usage {
    [Console]::Error.WriteLine("usage: .sc-lint/bootstrap.ps1 <setup|lint|test|upgrade|exec> --config sc-lint.toml [--check] [--dry-run]; .sc-lint/bootstrap.ps1 lint [selector] [host|all|linux|macos|windows] --config sc-lint.toml; .sc-lint/bootstrap.ps1 exec [--config sc-lint.toml] -- <argv...>")
    exit 2
}

if ($Operation -notin @("setup", "lint", "test", "upgrade", "exec")) { Stop-Usage }

if ($Operation -eq "exec") {
    $execConfig = $null
    $execArguments = @()
    $separatorFound = $false
    for ($index = 0; $index -lt $Rest.Count; $index++) {
        if ($Rest[$index] -eq "--config") {
            if ($index + 1 -ge $Rest.Count) { Stop-Usage }
            $execConfig = $Rest[$index + 1]
            $index++
        } elseif ($Rest[$index] -eq "--") {
            if ($index + 1 -lt $Rest.Count) {
                $execArguments = @($Rest[($index + 1)..($Rest.Count - 1)])
            }
            $separatorFound = $true
            break
        } else {
            # Some Windows pwsh -File invocations consume the literal `--`
            # before populating $args. In that case, the first token that is
            # not an exec option is the command, and the rest are its argv.
            $execArguments = @($Rest[$index..($Rest.Count - 1)])
            $separatorFound = $true
            break
        }
    }
    if (-not $separatorFound -or $execArguments.Count -eq 0) { Stop-Usage }

    $execBinary = $null
    $hasExecBinaryOverride = -not [string]::IsNullOrWhiteSpace($env:SC_LINT_BIN)
    if ($hasExecBinaryOverride) {
        $resolvedExecBinary = Get-Command -Name $env:SC_LINT_BIN -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($resolvedExecBinary) { $execBinary = $resolvedExecBinary.Path }
    } else {
        if ($env:SC_LINT_INSTALL_DIR) {
            $execInstallDirectory = $env:SC_LINT_INSTALL_DIR
        } else {
            $localAppData = if ($env:LOCALAPPDATA) { $env:LOCALAPPDATA } else { Join-Path $HOME "AppData\Local" }
            $execInstallDirectory = Join-Path (Join-Path $localAppData "sc-lint") "bin"
        }
        $execBinary = Join-Path $execInstallDirectory "sc-lint.exe"
    }
    if (-not $execBinary) {
        [Console]::Error.WriteLine("sc-lint binary is unavailable at $($env:SC_LINT_BIN); run just setup")
        exit 1
    }
    $resolvedExecBinary = Get-Command -Name $execBinary -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
    if (-not $resolvedExecBinary -or -not (Test-Path -LiteralPath $resolvedExecBinary.Path -PathType Leaf)) {
        [Console]::Error.WriteLine("sc-lint binary is unavailable at $execBinary; run just setup")
        exit 1
    }
    $execBinary = $resolvedExecBinary.Path

    $env:SC_LINT_BIN = $execBinary
    $env:PATH = (Split-Path -Parent $execBinary) + [IO.Path]::PathSeparator + $env:PATH
    # PowerShell retains LASTEXITCODE between native invocations. Clear it so
    # non-native commands and launch failures cannot inherit a stale status.
    $global:LASTEXITCODE = $null
    $execSucceeded = $false
    try {
        if ($execArguments[0] -ceq "sc-lint") {
            $invokeArguments = @()
            if ($execConfig) { $invokeArguments += @("--config", $execConfig) }
            if ($execArguments.Count -gt 1) { $invokeArguments += @($execArguments | Select-Object -Skip 1) }
            & $execBinary @invokeArguments
            $execSucceeded = $?
        } elseif ([IO.Path]::GetExtension($execArguments[0]) -in @(".cmd", ".bat")) {
            # PowerShell's direct batch-file invocation reports success even
            # when the batch file exits nonzero. Route batch commands through
            # cmd.exe so LASTEXITCODE preserves ERRORLEVEL.
            $commandProcessor = if ($env:ComSpec) { $env:ComSpec } else { Join-Path $env:SystemRoot "System32\cmd.exe" }
            $childArguments = @($execArguments | Select-Object -Skip 1)
            & $commandProcessor /d /c $execArguments[0] @childArguments
            $execSucceeded = $?
        } else {
            $childArguments = @($execArguments | Select-Object -Skip 1)
            & $execArguments[0] @childArguments
            $execSucceeded = $?
        }
    } catch {
        [Console]::Error.WriteLine($_.Exception.Message)
        $execSucceeded = $false
    }
    if ($null -ne $LASTEXITCODE) { exit $LASTEXITCODE }
    if (-not $execSucceeded) { exit 127 }
    exit 0
}

$configIndex = [Array]::IndexOf($Rest, "--config")
if ($configIndex -lt 0 -or $configIndex -eq ($Rest.Count - 1)) { Stop-Usage }
$Config = $Rest[$configIndex + 1]
$remaining = @()
for ($index = 0; $index -lt $Rest.Count; $index++) {
    if ($index -ne $configIndex -and $index -ne ($configIndex + 1)) { $remaining += $Rest[$index] }
}
$selector = @($remaining | Where-Object { $_ -notin @("--check", "--dry-run") })
# `lint [selector] [scope]`: one positional is always the selector, two are
# selector then platform scope; scope-only or more than two is a usage error.
$maxPositional = switch ($Operation) { "lint" { 2 } "test" { 1 } default { 0 } }
if ($selector.Count -gt $maxPositional) { Stop-Usage }
if ($selector.Count -eq 2 -and (-not $selector[0] -or -not $selector[1])) { Stop-Usage }

$installDirectory = if ($env:SC_LINT_INSTALL_DIR) { $env:SC_LINT_INSTALL_DIR } else { Join-Path $env:LOCALAPPDATA "sc-lint\\bin" }
$managedBinary = Join-Path $installDirectory "sc-lint.exe"
$productBinary = $null
$productBinaryOverride = $false

# Python helper package (sc_lint wheel) provisioned next to the config file.
$venvDirectory = Join-Path (Split-Path -Parent (Resolve-Path -LiteralPath $Config).Path) ".sc-lint\venv"
$venvPython = Join-Path $venvDirectory "Scripts\python.exe"
# Consumer-declared tools (ADR-017 change 6) persist in the installer input next
# to the config file; the managed wheel helper sc_lint.setup_tools owns them.
$installInput = Join-Path (Split-Path -Parent (Resolve-Path -LiteralPath $Config).Path) ".sc-lint\install.json"
# Seed-interpreter probe (stdlib JSON only): exit 0 when the tools object is
# absent or every collection is empty, 3 when the managed helper must run.
$toolsProbe = @'
import json, sys
try:
    with open(sys.argv[1], encoding='utf-8') as handle:
        data = json.load(handle)
except (OSError, ValueError):
    sys.exit(3)
tools = data.get('tools', {}) if isinstance(data, dict) else None
empty = {'cargo': {}, 'rustup_targets': []}
declared = not isinstance(tools, dict) or any(key not in empty or tools[key] != empty[key] for key in tools)
sys.exit(3 if declared else 0)
'@

function Get-MinimumVersion {
    $minimumLine = Select-String -Path $Config -Pattern '^\s*minimum_version\s*=\s*"([^"]+)"' | Select-Object -First 1
    if (-not $minimumLine) {
        [Console]::Error.WriteLine("setup: could not read minimum_version from $Config (CLI.SC_LINT_CONFIG_MALFORMED)")
        exit 3
    }
    return $minimumLine.Matches[0].Groups[1].Value
}

function Test-VenvReady {
    param([string]$Version)
    if (-not (Test-Path -LiteralPath $venvPython -PathType Leaf)) { return $false }
    $probe = "import sys, sc_lint`nparse = lambda v: tuple(int(p) for p in v.split('+')[0].split('.')[:3])`nsys.exit(0 if parse(sc_lint.__version__) >= parse(sys.argv[1]) else 1)"
    & $venvPython -c $probe $Version 2>$null | Out-Null
    return ($LASTEXITCODE -eq 0)
}

function Get-VenvMode {
    param([string[]]$Arguments)
    if ($Arguments -contains "--check") { return "check" }
    if ($Arguments -contains "--dry-run") { return "dry-run" }
    return "install"
}

function Get-SeedPython {
    $seedPython = Get-Command "python" -ErrorAction SilentlyContinue
    if (-not $seedPython) { $seedPython = Get-Command "python3" -ErrorAction SilentlyContinue }
    return $seedPython
}

# Ensure .sc-lint/venv holds sc-lint>=minimum_version. SC_LINT_WHEEL_DIR selects
# an offline wheel directory instead of PyPI.
function Install-Venv {
    param([string]$Mode)
    $version = Get-MinimumVersion
    if (Test-VenvReady $version) { return }
    if ($Mode -eq "check") {
        [Console]::Error.WriteLine("setup: $venvDirectory does not provide sc-lint>=$version (CLI.SC_LINT_PYTHON_UNAVAILABLE)")
        exit 4
    }
    if ($Mode -eq "dry-run") {
        Write-Output "setup: would install sc-lint==$version into $venvDirectory"
        return
    }
    if (-not (Test-Path -LiteralPath $venvPython -PathType Leaf)) {
        $hostPython = Get-SeedPython
        if (-not $hostPython) {
            [Console]::Error.WriteLine("setup: could not create $venvDirectory (CLI.SC_LINT_PYTHON_UNAVAILABLE)")
            exit 4
        }
        & $hostPython.Source -m venv $venvDirectory
        if ($LASTEXITCODE -ne 0) {
            [Console]::Error.WriteLine("setup: could not create $venvDirectory (CLI.SC_LINT_PYTHON_UNAVAILABLE)")
            exit 4
        }
    }
    $pipArguments = @("-m", "pip", "install", "--quiet", "--disable-pip-version-check")
    if ($env:SC_LINT_WHEEL_DIR) { $pipArguments += @("--no-index", "--find-links", $env:SC_LINT_WHEEL_DIR) }
    $pipArguments += "sc-lint==$version"
    & $venvPython @pipArguments
    if ($LASTEXITCODE -ne 0) {
        [Console]::Error.WriteLine("setup: could not install sc-lint==$version into $venvDirectory (CLI.SC_LINT_PYTHON_UNAVAILABLE)")
        exit 4
    }
}

# Run the managed sc_lint.setup_tools helper only when the persisted installer
# input declares tools. Dry-run and check forward --check and never provision
# the helper or any tool.
function Install-DeclaredTools {
    param([string]$Mode)
    $previousExitCode = $LASTEXITCODE
    if (-not (Test-Path -LiteralPath $installInput -PathType Leaf)) { return }
    $probePython = $null
    $seedPython = Get-SeedPython
    if ($seedPython) {
        $probePython = $seedPython.Source
    } elseif (Test-Path -LiteralPath $venvPython -PathType Leaf) {
        $probePython = $venvPython
    }
    if (-not $probePython) {
        [Console]::Error.WriteLine("setup: no Python is available to read the tools declaration in $installInput (SETUP_TOOLS.INSPECTION_UNAVAILABLE); install Python 3, then run just setup")
        exit 4
    }
    & $probePython -c $toolsProbe $installInput
    $toolsStatus = $LASTEXITCODE
    if ($toolsStatus -eq 0) {
        $global:LASTEXITCODE = $previousExitCode
        return
    }
    if ($toolsStatus -ne 3) {
        [Console]::Error.WriteLine("setup: could not read the tools declaration in $installInput (SETUP_TOOLS.INSPECTION_UNAVAILABLE); run just setup")
        exit 4
    }
    $helperReady = $false
    if (Test-Path -LiteralPath $venvPython -PathType Leaf) {
        & $venvPython -c "import sc_lint.setup_tools" 2>$null | Out-Null
        $helperReady = ($LASTEXITCODE -eq 0)
    }
    if (-not $helperReady) {
        if ($Mode -eq "install") {
            [Console]::Error.WriteLine("setup: $installInput declares tools, but the sc-lint wheel in $venvDirectory does not provide sc_lint.setup_tools (SETUP_TOOLS.INSPECTION_UNAVAILABLE); raise minimum_version, then run just setup")
        } else {
            [Console]::Error.WriteLine("setup: $installInput declares tools that cannot be inspected because sc_lint.setup_tools is unavailable in $venvDirectory (SETUP_TOOLS.INSPECTION_UNAVAILABLE); run just setup")
        }
        exit 4
    }
    $helperArguments = @("-m", "sc_lint.setup_tools", "--config", $Config)
    if ($Mode -ne "install") { $helperArguments += "--check" }
    & $venvPython @helperArguments
    if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
}

function Resolve-ProductBinary {
    $script:productBinaryOverride = $false
    if ($env:SC_LINT_BIN) {
        $resolved = Get-Command $env:SC_LINT_BIN -ErrorAction SilentlyContinue
        if ($resolved) {
            $script:productBinaryOverride = $true
            return $resolved.Source
        }
    }
    if (Test-Path -Path $managedBinary -PathType Leaf) { return $managedBinary }
    $resolved = Get-Command "sc-lint" -ErrorAction SilentlyContinue
    if ($resolved) { return $resolved.Source }
    return $null
}

function Test-ManagedBinary {
    param([string]$Binary)
    if (-not $Binary -or -not (Test-Path -LiteralPath $Binary -PathType Leaf)) { return $false }
    if (-not (Test-Path -LiteralPath $managedBinary -PathType Leaf)) { return $false }
    $resolvedBinary = (Resolve-Path -LiteralPath $Binary).Path
    $resolvedManaged = (Resolve-Path -LiteralPath $managedBinary).Path
    return [string]::Equals($resolvedBinary, $resolvedManaged, [System.StringComparison]::OrdinalIgnoreCase)
}

function Invoke-VerifiedReleaseLauncher {
    param([string]$Command, [string[]]$Arguments)
    $minimumLine = Select-String -Path $Config -Pattern '^\s*minimum_version\s*=\s*"([^"]+)"' | Select-Object -First 1
    if (-not $minimumLine) {
        [Console]::Error.WriteLine("setup: could not read minimum_version from $Config (CLI.SC_LINT_CONFIG_MALFORMED)")
        exit 3
    }
    $version = $minimumLine.Matches[0].Groups[1].Value
    if ($env:PROCESSOR_ARCHITECTURE -notin @("AMD64", "x86_64")) {
        [Console]::Error.WriteLine("setup: no verified sc-lint release for Windows/$env:PROCESSOR_ARCHITECTURE (CLI.SC_LINT_INSTALL_UNSUPPORTED_PLATFORM)")
        exit 4
    }
    $archive = "sc-lint_${version}_x86_64-pc-windows-msvc.zip"
    $base = if ($env:SC_LINT_RELEASE_BASE_URL) { $env:SC_LINT_RELEASE_BASE_URL.TrimEnd('/') } else { "https://github.com/randlee/sc-lint/releases/download" }
    $releaseUrl = "$base/v$version"
    $staging = Join-Path ([System.IO.Path]::GetTempPath()) ("sc-lint-bootstrap-" + [System.Guid]::NewGuid().ToString("N"))
    try {
        New-Item -ItemType Directory -Path $staging -Force | Out-Null
        $checksums = Join-Path $staging "checksums.txt"
        $archivePath = Join-Path $staging $archive
        Invoke-WebRequest -UseBasicParsing -Uri "$releaseUrl/checksums.txt" -OutFile $checksums
        Invoke-WebRequest -UseBasicParsing -Uri "$releaseUrl/$archive" -OutFile $archivePath
        $expectedLine = Get-Content $checksums | Where-Object { $_ -match ("\s\*?" + [regex]::Escape($archive) + "$") } | Select-Object -First 1
        if (-not $expectedLine) { throw "checksum manifest did not contain $archive" }
        $expected = ($expectedLine -split '\s+')[0]
        $actual = (Get-FileHash -Algorithm SHA256 -Path $archivePath).Hash
        if ($actual -ne $expected) { throw "SHA-256 verification failed for $archive" }
        $extract = Join-Path $staging "extract"
        Expand-Archive -Path $archivePath -DestinationPath $extract -Force
        $candidate = Join-Path $extract "sc-lint.exe"
        if (-not (Test-Path -Path $candidate -PathType Leaf)) {
            $candidate = Join-Path (Join-Path (Join-Path $extract "sc-lint_${version}_x86_64-pc-windows-msvc") "bin") "sc-lint.exe"
        }
        if (-not (Test-Path -Path $candidate -PathType Leaf)) { throw "release archive did not contain sc-lint.exe" }
        New-Item -ItemType Directory -Path $installDirectory -Force | Out-Null
        # The extracted release is only a launcher. It delegates managed-target
        # activation to its Rust installer, which preserves backup, rollback,
        # and post-install version verification.
        & $candidate --config $Config $Command @Arguments
        if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
    } catch {
        [Console]::Error.WriteLine("setup: $($_.Exception.Message) (CLI.SC_LINT_RELEASE_UNAVAILABLE)")
        exit 4
    } finally {
        if (Test-Path $staging) { Remove-Item -Recurse -Force $staging }
    }
}

function Ensure-Product {
    $script:productBinary = Resolve-ProductBinary
    if (-not $script:productBinary) {
        Invoke-VerifiedReleaseLauncher "setup" $remaining
        $script:productBinary = $managedBinary
    }
    & $script:productBinary --config $Config compatibility check --binary $script:productBinary
    if ($LASTEXITCODE -ne 0) {
        if (Test-ManagedBinary $script:productBinary) {
            if ($remaining -contains "--check" -or $remaining -contains "--dry-run") {
                & $script:productBinary --config $Config setup @remaining
                if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
            } else {
                Invoke-VerifiedReleaseLauncher "setup" $remaining
            }
            $script:productBinary = $managedBinary
        } elseif ($script:productBinaryOverride -or $remaining -contains "--check" -or $remaining -contains "--dry-run") {
            & $script:productBinary --config $Config setup @remaining
            if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
        } else {
            Invoke-VerifiedReleaseLauncher "setup" $remaining
            $script:productBinary = $managedBinary
        }
    }
}

function Enter-ProductEnvironment {
    $env:SC_LINT_BIN = $productBinary
    $env:PATH = (Split-Path -Parent $productBinary) + [IO.Path]::PathSeparator + $env:PATH
}

switch ($Operation) {
    "setup" {
        Ensure-Product
        & $productBinary --config $Config setup @remaining
        if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
        $setupMode = Get-VenvMode $remaining
        Install-Venv $setupMode
        Install-DeclaredTools $setupMode
    }
    "lint" {
        Ensure-Product
        Enter-ProductEnvironment
        Install-Venv "install"
        $lintArguments = @("lint", "--consumer", "--config", $Config, "ci")
        if ($selector.Count -ge 1 -and $selector[0]) { $lintArguments += @("--profile", $selector[0]) }
        if ($selector.Count -eq 2) { $lintArguments += @("--platform-scope", $selector[1]) }
        & $productBinary @lintArguments
        $lintSucceeded = $?
        $lintExitCode = $LASTEXITCODE
        if ($null -ne $lintExitCode) { exit $lintExitCode }
        if (-not $lintSucceeded) { exit 1 }
        exit 0
    }
    "test" {
        Ensure-Product
        Enter-ProductEnvironment
        Install-Venv "install"
        if ($selector.Count -eq 1) { & $productBinary test --config $Config $selector[0] } else { & $productBinary test --config $Config }
    }
    "upgrade" {
        $productBinary = Resolve-ProductBinary
        if (-not $productBinary) {
            Invoke-VerifiedReleaseLauncher "upgrade" $remaining
            exit $LASTEXITCODE
        }
        & $productBinary --config $Config compatibility check --binary $productBinary
        if ($LASTEXITCODE -ne 0 -and (Test-ManagedBinary $productBinary) -and $remaining -notcontains "--check" -and $remaining -notcontains "--dry-run") {
            Invoke-VerifiedReleaseLauncher "upgrade" $remaining
        } elseif ($LASTEXITCODE -ne 0 -and -not $productBinaryOverride -and $remaining -notcontains "--check" -and $remaining -notcontains "--dry-run") {
            Invoke-VerifiedReleaseLauncher "upgrade" $remaining
            exit $LASTEXITCODE
        } else {
            & $productBinary --config $Config upgrade @remaining
            if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
            Install-Venv (Get-VenvMode $remaining)
        }
    }
}
exit $LASTEXITCODE
